/*
 * 书本点击展开动效 — 开发直接接入版
 * 本文件内置全部图片、样式和动画代码，无需额外素材或第三方库。
 * 将本文件放入网站静态资源目录，在页面中使用：
 *
 * <div id="culture-scene"></div>
 * <script src="./culture-book.js"></script>
 * <script>
 *   const scene = new CultureScene('#culture-scene');
 * </script>
 *
 * 加载完成先显示书本，点击书本后星光向外展开，泡泡依次浮现，
 * 最后粉色文字从左向右出现，约 12 秒结束并停留在完整原图。
 * 容器跟随父元素宽度缩放，画面比例为 1672:941。
 *
 * 控制：await scene.ready; scene.play(); scene.pause(); scene.resume();
 *       scene.reset(); scene.seek(6); scene.destroy();
 * reset() 恢复书本入口，随后可再次点击播放。
 * 自定义按钮：new CultureScene('#culture-scene', { trigger: false });
 *             然后在按钮点击事件中调用 scene.play()。
 * React / Vue：元素挂载后创建实例，卸载时调用 scene.destroy()。
 * 完成事件：scene.element.addEventListener('culture:complete', handler)。
 * 尊重系统减少动态效果设置；该设置启用时，点击后直接显示完整画面。
 *
 * 下方首先是可编辑代码，图片数据位于文件末尾。
 */
(function (global) {
  'use strict';

  function ensureStyles() {
    if (document.getElementById('culture-book-styles')) return;
    const style = document.createElement('style');
    style.id = 'culture-book-styles';
    style.textContent = ".culture-scene {\n  position: relative;\n  width: 100%;\n  aspect-ratio: 1672 / 941;\n  overflow: hidden;\n  isolation: isolate;\n  background: #122258;\n  font-family: \"Microsoft YaHei\", \"PingFang SC\", sans-serif;\n}\n\n.culture-scene__canvas {\n  display: block;\n  width: 100%;\n  height: 100%;\n}\n\n.culture-scene__trigger {\n  position: absolute;\n  left: 54.486%;\n  top: 45.909%;\n  transform: translate(-50%, -50%);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  width: 13%;\n  height: 15%;\n  min-width: 44px;\n  min-height: 44px;\n  padding: 0;\n  border: 0;\n  border-radius: 50%;\n  background: transparent;\n  color: transparent;\n  cursor: pointer;\n  -webkit-tap-highlight-color: transparent;\n  touch-action: manipulation;\n  transition: box-shadow .2s;\n}\n\n.culture-scene__trigger:hover {\n  box-shadow: 0 0 30px #ffdcad55, inset 0 0 20px #ffdcad18;\n}\n\n.culture-scene__trigger:focus-visible {\n  outline: 2px solid #fff3cc;\n  outline-offset: 6px;\n  box-shadow: 0 0 30px #ffdcad55;\n}\n\n.culture-scene__trigger:disabled {\n  opacity: .7;\n  cursor: progress;\n}\n\n.culture-scene__trigger[hidden] { display: none; }\n\n.culture-scene__status {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  padding: 0;\n  overflow: hidden;\n  clip-path: inset(50%);\n  white-space: nowrap;\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .culture-scene__trigger { transition: none; }\n}\n";
    (document.head || document.documentElement).append(style);
  }

  const clamp = (value, min, max) => Math.max(min, Math.min(max, value));
  const smooth = value => { const p = clamp(value, 0, 1); return p * p * (3 - 2 * p); };
  const easeOut = value => 1 - Math.pow(1 - clamp(value, 0, 1), 3);

  function loadImage(src) {
    return new Promise((resolve, reject) => {
      const image = new Image();
      image.onload = () => resolve(image);
      image.onerror = () => reject(new Error('图片加载失败：' + src.slice(0, 160)));
      image.src = src;
    });
  }

  class CultureScene {
    constructor(target, options = {}) {
      ensureStyles();
      this.element = typeof target === 'string' ? document.querySelector(target) : target;
      if (!this.element) throw new Error('找不到动效容器');
      this.data = options.data || BUILTIN_SCENE_DATA;
      this.options = { assetsBase: './assets/', trigger: 'auto', ...options };
      this.duration = this.data.duration;
      this.currentTime = 0;
      this.state = 'loading';
      this._frameId = null;
      this._pendingPlay = false;
      this._originalState = this.element.getAttribute('data-state');
      this._hadSceneClass = this.element.classList.contains('culture-scene');
      this.element.classList.add('culture-scene');
      this.element.dataset.state = 'loading';

      this.canvas = document.createElement('canvas');
      this.canvas.className = 'culture-scene__canvas';
      this.canvas.width = this.data.width;
      this.canvas.height = this.data.height;
      this.canvas.setAttribute('role', 'img');
      this.canvas.setAttribute('aria-label', '少年与小狗仰望星空，点击中间的书后，星光向外延伸，文化泡泡依次浮现，最后出现粉色文字');
      this.ctx = this.canvas.getContext('2d', { alpha: false });
      if (!this.ctx) throw new Error('当前浏览器不支持画布');
      this.element.append(this.canvas);

      this.scratch = document.createElement('canvas');
      this.scratch.width = this.data.width;
      this.scratch.height = this.data.height;
      this.sctx = this.scratch.getContext('2d');
      this.status = document.createElement('span');
      this.status.className = 'culture-scene__status';
      this.status.setAttribute('role', 'status');
      this.status.textContent = '正在准备星空';
      this.element.append(this.status);

      if (this.options.trigger !== false) {
        this.trigger = document.createElement('button');
        this.trigger.type = 'button';
        this.trigger.className = 'culture-scene__trigger';
        this.trigger.setAttribute('aria-label', '正在准备书本');
        this.trigger.title = '点击书本，开启文化之旅';
        this.trigger.disabled = true;
        this._triggerHandler = () => this.play();
        this.trigger.addEventListener('click', this._triggerHandler);
        this.element.append(this.trigger);
      }

      this._visibilityHandler = () => {
        // Pause on a hidden tab so returning visitors never miss the reveal.
        if (document.hidden && this.state === 'playing') this.pause();
      };
      document.addEventListener('visibilitychange', this._visibilityHandler);
      this._tick = now => {
        this._frameId = null;
        if (this.state !== 'playing') return;
        this.currentTime = clamp((now - this._origin) / 1000, 0, this.duration);
        this._draw(this.currentTime);
        if (this.currentTime >= this.duration) {
          this._setState('complete');
          this._emit('complete');
        } else {
          this._frameId = requestAnimationFrame(this._tick);
        }
      };

      this.ready = this._load().catch(error => {
        if (this.state !== 'destroyed') {
          this._setState('error');
          this.status.textContent = '图片加载失败，请检查图片路径并重新打开页面。';
          if (this.trigger) {
            this.trigger.disabled = true;
            this.trigger.setAttribute('aria-label', '图片未加载');
          }
          this._emit('error', { error });
        }
        throw error;
      });
      // Consumers can still await/catch ready; avoid an unhandled rejection if
      // a host page relies only on the visible loading error.
      this.ready.catch(() => {});
    }

    _url(source) {
      return /^(data:|blob:|https?:|\/)/i.test(source)
        ? source
        : this.options.assetsBase.replace(/\/?$/, '/') + source;
    }

    async _load() {
      const images = await Promise.all([
        loadImage(this._url(this.data.background)),
        loadImage(this._url(this.data.original)),
        ...this.data.layers.map(layer => loadImage(this._url(layer.src)))
      ]);
      if (this.state === 'destroyed') return this;
      [this.background, this.original] = images;
      this.layers = this.data.layers.map((layer, i) => ({ ...layer, image: images[i + 2] }));
      this.orbit = this.layers.find(layer => layer.kind === 'orbit');
      this.book = this.layers.find(layer => layer.name === 'book');
      this.origin = this.book
        ? { x: this.book.x + this.book.w / 2, y: this.book.y + this.book.h / 2 }
        : { x: this.data.width / 2, y: this.data.height / 2 };
      this.bubbles = this.layers.filter(layer => layer.kind === 'bubble' && layer !== this.book);
      this.wipes = this.layers.filter(layer => layer.kind === 'wipe');
      this._draw(0);
      this._setState('idle');
      this._emit('ready');
      if (this._pendingPlay) this.play();
      return this;
    }

    _emit(name, extra = {}) {
      this.element.dispatchEvent(new CustomEvent('culture:' + name, {
        bubbles: true,
        detail: { time: this.currentTime, duration: this.duration, state: this.state, ...extra }
      }));
    }

    _setState(state) {
      this.state = state;
      this.element.dataset.state = state;
      if (this.trigger) {
        this.trigger.disabled = state === 'loading' || state === 'error';
        this.trigger.hidden = state === 'playing' || state === 'complete';
        const label = state === 'paused' ? '点击书本，继续文化之旅' : '点击书本，开启文化之旅';
        this.trigger.setAttribute('aria-label', label);
        this.trigger.title = label;
      }
      const labels = {
        idle: '点击中间的书，开启文化之旅',
        playing: '文化之旅正在展开',
        paused: '动效已暂停',
        complete: '文化之旅已完整展现'
      };
      if (labels[state]) this.status.textContent = labels[state];
    }

    _stopFrame() {
      if (this._frameId !== null) cancelAnimationFrame(this._frameId);
      this._frameId = null;
    }

    _drawWipe(layer, progress) {
      if (progress <= 0) return;
      if (progress >= 1) {
        this.ctx.drawImage(layer.image, layer.x, layer.y, layer.w, layer.h);
        return;
      }
      const { sctx, scratch } = this;
      sctx.clearRect(0, 0, scratch.width, scratch.height);
      sctx.drawImage(layer.image, layer.x, layer.y, layer.w, layer.h);
      sctx.globalCompositeOperation = 'destination-in';
      const feather = 36;
      const edge = layer.x - 2 * feather + (layer.w + 4 * feather) * progress;
      const gradient = sctx.createLinearGradient(edge - feather, 0, edge + feather, 0);
      gradient.addColorStop(0, 'rgba(255,255,255,1)');
      gradient.addColorStop(1, 'rgba(255,255,255,0)');
      sctx.fillStyle = gradient;
      sctx.fillRect(0, 0, scratch.width, scratch.height);
      sctx.globalCompositeOperation = 'source-over';
      this.ctx.drawImage(scratch, 0, 0);
    }

    _drawOrbit(layer, progress) {
      if (progress <= 0) return;
      if (progress >= 1) {
        this.ctx.drawImage(layer.image, layer.x, layer.y, layer.w, layer.h);
        return;
      }
      const { sctx, scratch, origin } = this;
      const dx = Math.max(Math.abs(layer.x - origin.x), Math.abs(layer.x + layer.w - origin.x));
      const dy = Math.max(Math.abs(layer.y - origin.y), Math.abs(layer.y + layer.h - origin.y));
      const feather = 36;
      const radius = (Math.hypot(dx, dy) + feather) * progress;
      sctx.clearRect(0, 0, scratch.width, scratch.height);
      sctx.drawImage(layer.image, layer.x, layer.y, layer.w, layer.h);
      sctx.globalCompositeOperation = 'destination-in';
      const gradient = sctx.createRadialGradient(
        origin.x, origin.y, Math.max(0, radius - feather),
        origin.x, origin.y, radius + feather
      );
      gradient.addColorStop(0, 'rgba(255,255,255,1)');
      gradient.addColorStop(1, 'rgba(255,255,255,0)');
      sctx.fillStyle = gradient;
      sctx.fillRect(0, 0, scratch.width, scratch.height);
      sctx.globalCompositeOperation = 'source-over';
      this.ctx.drawImage(scratch, 0, 0);
    }

    _draw(time) {
      const t = clamp(time, 0, this.duration);
      const { ctx, data, orbit, book, origin } = this;
      ctx.globalAlpha = 1;
      ctx.globalCompositeOperation = 'source-over';
      ctx.drawImage(this.background, 0, 0, data.width, data.height);
      if (orbit && t > orbit.start) {
        ctx.globalAlpha = smooth((t - orbit.start) / .9);
        this._drawOrbit(orbit, easeOut((t - orbit.start) / orbit.duration));
        ctx.globalAlpha = 1;
      }
      // The book is visible before the interaction and gently responds to it.
      if (book) {
        const pulse = 1 + .023 * Math.sin(Math.PI * clamp(t / .9, 0, 1));
        ctx.save();
        ctx.translate(origin.x, origin.y);
        ctx.scale(pulse, pulse);
        ctx.drawImage(book.image, -book.w / 2, -book.h / 2, book.w, book.h);
        ctx.restore();
      }
      for (const layer of this.bubbles) {
        const p = (t - layer.start) / layer.duration;
        if (p <= 0) continue;
        const e = easeOut(p);
        const settle = 1 - smooth((t - 8.9) / 1.15);
        const float = p >= 1 ? Math.sin((t - layer.start) * 1.75 + layer.start) * 2.1 * settle : 0;
        const scale = .84 + .16 * e;
        const x = layer.x + layer.w / 2;
        const y = layer.y + layer.h / 2;
        const distance = Math.hypot(origin.x - x, origin.y - y);
        const travel = Math.min(64, distance * .14) * (1 - e);
        const dx = distance ? (origin.x - x) / distance * travel : 0;
        const dy = (distance ? (origin.y - y) / distance * travel : 0) + float;
        ctx.save();
        ctx.globalAlpha = smooth(p);
        ctx.translate(x + dx, y + dy);
        ctx.scale(scale, scale);
        ctx.drawImage(layer.image, -layer.w / 2, -layer.h / 2, layer.w, layer.h);
        ctx.restore();
      }
      for (const layer of this.wipes) {
        this._drawWipe(layer, clamp((t - layer.start) / layer.duration, 0, 1));
      }
      // Match every final artwork pixel after the animated layers settle.
      const lock = smooth((t - 9.97) / .33);
      if (lock > 0) {
        ctx.globalAlpha = lock;
        ctx.drawImage(this.original, 0, 0, data.width, data.height);
        ctx.globalAlpha = 1;
      }
    }

    play() {
      if (this.state === 'destroyed' || this.state === 'error') return this;
      if (this.state === 'loading') { this._pendingPlay = true; return this; }
      if (this.state === 'playing') return this;
      if (this.state === 'paused') return this.resume();
      this._pendingPlay = false;
      this.currentTime = 0;
      this._draw(0);
      this._setState('playing');
      this._emit('start');
      if (global.matchMedia?.('(prefers-reduced-motion: reduce)').matches) {
        this.currentTime = this.duration;
        this._draw(this.duration);
        this._setState('complete');
        this._emit('complete');
        return this;
      }
      this._origin = performance.now();
      this._frameId = requestAnimationFrame(this._tick);
      return this;
    }

    pause() {
      if (this.state !== 'playing') return this;
      this._stopFrame();
      this.currentTime = clamp((performance.now() - this._origin) / 1000, 0, this.duration);
      this._draw(this.currentTime);
      this._setState('paused');
      this._emit('pause');
      return this;
    }

    resume() {
      if (this.state !== 'paused') return this;
      this._setState('playing');
      this._origin = performance.now() - this.currentTime * 1000;
      this._frameId = requestAnimationFrame(this._tick);
      this._emit('resume');
      return this;
    }

    reset() {
      if (this.state === 'destroyed') return this;
      this._pendingPlay = false;
      this._stopFrame();
      this.currentTime = 0;
      if (this.background) {
        this._draw(0);
        this._setState('idle');
        this._emit('reset');
      }
      return this;
    }

    seek(seconds) {
      if (!this.background || this.state === 'destroyed') return this;
      if (!Number.isFinite(Number(seconds))) throw new TypeError('时间必须为秒数');
      this._stopFrame();
      this.currentTime = clamp(Number(seconds), 0, this.duration);
      this._draw(this.currentTime);
      this._setState(this.currentTime === 0 ? 'idle' : this.currentTime === this.duration ? 'complete' : 'paused');
      this._emit('seek');
      return this;
    }

    destroy() {
      if (this.state === 'destroyed') return;
      this._pendingPlay = false;
      this._stopFrame();
      document.removeEventListener('visibilitychange', this._visibilityHandler);
      this.trigger?.removeEventListener('click', this._triggerHandler);
      this.canvas.remove();
      this.status.remove();
      this.trigger?.remove();
      if (!this._hadSceneClass) this.element.classList.remove('culture-scene');
      if (this._originalState === null) this.element.removeAttribute('data-state');
      else this.element.setAttribute('data-state', this._originalState);
      this.state = 'destroyed';
    }
  }

  // 内置图片与时间轴。修改时保留完整 data:image/png;base64 数据。
  const BUILTIN_SCENE_DATA = {"width":1672,"height":941,"duration":12,"background":"data:image/png;base64,","original":"data:image/png;base64,","layers":[{"name":"book","x":700,"y":233,"w":424,"h":397,"kind":"bubble","start":0.75,"duration":1.2,"src":"data:image/png;base64,"},{"name":"pyramid","x":261,"y":193,"w":300,"h":284,"kind":"bubble","start":2,"duration":1.05,"src":"data:image/png;base64,"},{"name":"temple","x":495,"y":44,"w":350,"h":329,"kind":"bubble","start":2.8,"duration":1.05,"src":"data:image/png;base64,"},{"name":"colosseum","x":1074,"y":93,"w":320,"h":299,"kind":"bubble","start":3.6,"duration":1.05,"src":"data:image/png;base64,"},{"name":"castle","x":1237,"y":295,"w":337,"h":325,"kind":"bubble","start":4.4,"duration":1.05,"src":"data:image/png;base64,"},{"name":"small-left","x":113,"y":108,"w":144,"h":141,"kind":"bubble","start":5.05,"duration":0.8,"src":"data:image/png;base64,"},{"name":"small-middle","x":515,"y":533,"w":130,"h":124,"kind":"bubble","start":5.25,"duration":0.8,"src":"data:image/png;base64,"},{"name":"small-right","x":1441,"y":560,"w":173,"h":172,"kind":"bubble","start":5.45,"duration":0.8,"src":"data:image/png;base64,"},{"name":"text-first","x":605,"y":563,"w":780,"h":133,"kind":"wipe","start":6,"duration":1.8,"src":"data:image/png;base64,"},{"name":"text-second","x":571,"y":637,"w":835,"h":113,"kind":"wipe","start":7.6,"duration":1.9,"src":"data:image/png;base64,"},{"name":"signature","x":671,"y":661,"w":795,"h":133,"kind":"wipe","start":9.35,"duration":0.85,"src":"data:image/png;base64,"},{"name":"orbits","x":92,"y":0,"w":1580,"h":839,"kind":"orbit","start":0.15,"duration":5.15,"src":"data:image/png;base64,"}]};

  global.CultureScene = CultureScene;
})(window);
